parameters.jsCode:
const body = $input.first().json.body;
const projectKey = body.projectKey || 'JIRA-PROJECT';
const epicsCount = body.epicsCount || 1;
const storiesCount = body.storiesCount || 5;
const jiraUrl = body.jiraUrl || 'https://atlassian.net';

const discordPayload = {
  username: 'AI Jira Agent',
  avatar_url: 'https://cdn-icons-png.flaticon.com/512/5968/5968875.png',
  embeds: [
    {
      title: '🚀 [THÀNH CÔNG] Đã tạo Backlog mới trên Jira!',
      color: 3066993,
      description: `Đã phân rã và đẩy thành công các Epic & Story vào dự án **${projectKey}**.`,
      fields: [
        { name: 'Số lượng Epic', value: `${epicsCount}`, inline: true },
        { name: 'Số lượng Story/Task', value: `${storiesCount}`, inline: true },
        { name: 'Đường dẫn Jira', value: `[Mở bảng công việc](${jiraUrl})` }
      ],
      footer: { text: 'AI Requirement-to-Jira • Automation by n8n' },
      timestamp: new Date().toISOString()
    }
  ]
};

return {
  json: {
    discordWebhookUrl: body.discordWebhookUrl,
    discordPayload
  }
};

